#[test]
fn a_judgment_that_fails_midway_leaves_no_rows() {
    let mut log = SqliteLog::in_memory().unwrap();
    let mut r = row("ai", "verified");
    // 2つ目の rule の結果を決まりに無い値にし、rule_results の2行目で失敗させる
    r.results.push(RuleRow {
        rule: "r2".into(),
        pointer: "/goal".into(),
        by: "ai".into(),
        result: "決まりに無い結果".into(),
        reason: "理由".into(),
        reads: "sha256:r".into(),
    });
    assert!(log.append_validate(None, &r).is_err());
    assert_eq!(count(&log, "validations"), 0);
    assert_eq!(count(&log, "rule_results"), 0, "1行目の判定が残った");
}

